import { act, render, screen } from '@testing-library/react'
import { http, HttpResponse } from 'msw'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { servidor } from '../../testes/servidor.js'
import { TelaCodigoEncontro } from './TelaCodigoEncontro.jsx'

describe('TelaCodigoEncontro', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2026-10-19T19:00:30-03:00'))
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('mostra o código atual assim que a tela abre', async () => {
    servidor.use(
      http.get('/encontros/enc_11111111/codigo', () =>
        HttpResponse.json({
          encontroId: 'enc_11111111',
          codigo: 'K7M2QX',
          trocaEm: '2026-10-19T19:01:00-03:00',
          validoAte: '2026-10-19T19:02:00-03:00',
        }),
      ),
    )

    render(<TelaCodigoEncontro encontroId="enc_11111111" usuarioId="org-ana" />)

    await act(async () => {
      await vi.advanceTimersByTimeAsync(0)
    })

    expect(screen.getByText('K7M2QX')).toBeInTheDocument()
  })

  it('busca o próximo código automaticamente quando o relógio chega em trocaEm', async () => {
    let chamadas = 0
    servidor.use(
      http.get('/encontros/enc_11111111/codigo', () => {
        chamadas += 1
        return chamadas === 1
          ? HttpResponse.json({
              encontroId: 'enc_11111111',
              codigo: 'K7M2QX',
              trocaEm: '2026-10-19T19:01:00-03:00',
              validoAte: '2026-10-19T19:02:00-03:00',
            })
          : HttpResponse.json({
              encontroId: 'enc_11111111',
              codigo: 'B34XCT',
              trocaEm: '2026-10-19T19:02:00-03:00',
              validoAte: '2026-10-19T19:03:00-03:00',
            })
      }),
    )

    render(<TelaCodigoEncontro encontroId="enc_11111111" usuarioId="org-ana" />)

    await act(async () => {
      await vi.advanceTimersByTimeAsync(0)
    })
    expect(screen.getByText('K7M2QX')).toBeInTheDocument()

    await act(async () => {
      await vi.advanceTimersByTimeAsync(30_000)
    })

    expect(screen.getByText('B34XCT')).toBeInTheDocument()
    expect(chamadas).toBe(2)
  })

  it('mostra o erro da API, como FORA_DA_JANELA', async () => {
    servidor.use(
      http.get('/encontros/enc_11111111/codigo', () =>
        HttpResponse.json({ erro: 'FORA_DA_JANELA', mensagem: 'fora da janela' }, { status: 422 }),
      ),
    )

    render(<TelaCodigoEncontro encontroId="enc_11111111" usuarioId="org-ana" />)

    await act(async () => {
      await vi.advanceTimersByTimeAsync(0)
    })

    expect(screen.getByRole('alert')).toHaveTextContent('FORA_DA_JANELA')
  })
})

import { useEffect, useState } from 'react'
import { chamarApi, ErroApi } from '../../api/cliente.js'

export function TelaCodigoEncontro({ encontroId, usuarioId }) {
  const [codigoDoEncontro, setCodigoDoEncontro] = useState(null)
  const [erro, setErro] = useState(null)

  useEffect(() => {
    let cancelado = false
    let temporizador

    async function buscar() {
      try {
        const dados = await chamarApi(`/encontros/${encontroId}/codigo`, { usuarioId })
        if (cancelado) return
        setCodigoDoEncontro(dados)
        setErro(null)
        const espera = Math.max(0, new Date(dados.trocaEm).getTime() - Date.now())
        temporizador = setTimeout(buscar, espera)
      } catch (e) {
        if (!cancelado) setErro(e)
      }
    }

    buscar()

    return () => {
      cancelado = true
      clearTimeout(temporizador)
    }
  }, [encontroId, usuarioId])

  return (
    <section>
      <h1>Código do encontro</h1>

      {erro && (
        <p role="alert">
          {erro instanceof ErroApi ? erro.codigo : 'Não foi possível carregar o código.'}
        </p>
      )}

      {codigoDoEncontro && <p className="codigo-do-encontro">{codigoDoEncontro.codigo}</p>}
    </section>
  )
}

import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { http, HttpResponse } from 'msw'
import { describe, expect, it } from 'vitest'
import { servidor } from '../../testes/servidor.js'
import { TelaLeituraPresenca } from './TelaLeituraPresenca.jsx'

describe('TelaLeituraPresenca', () => {
  it('envia o código digitado e mostra mensagem de sucesso', async () => {
    let corpoRecebido = null
    servidor.use(
      http.post('/encontros/enc_11111111/presencas', async ({ request }) => {
        expect(request.headers.get('X-Usuario')).toBe('p-carla')
        corpoRecebido = await request.json()
        return HttpResponse.json(
          {
            id: 'pre_11111111',
            encontroId: 'enc_11111111',
            participanteId: 'p-carla',
            origem: 'qr',
            lidoEm: '2026-10-19T19:00:30-03:00',
            registradaEm: '2026-10-19T19:00:30-03:00',
            justificativa: null,
          },
          { status: 201 },
        )
      }),
    )

    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-carla" />)

    await userEvent.type(screen.getByLabelText(/código/i), 'K7M2QX')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))

    expect(await screen.findByText(/presença registrada/i)).toBeInTheDocument()
    expect(corpoRecebido).toEqual({ codigo: 'K7M2QX' })
  })

  it('mostra FORA_DA_JANELA quando a API recusa por causa do horário', async () => {
    servidor.use(
      http.post('/encontros/enc_11111111/presencas', () =>
        HttpResponse.json({ erro: 'FORA_DA_JANELA', mensagem: 'fora da janela' }, { status: 422 }),
      ),
    )

    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-carla" />)

    await userEvent.type(screen.getByLabelText(/código/i), 'K7M2QX')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))

    expect(await screen.findByRole('alert')).toHaveTextContent('FORA_DA_JANELA')
  })

  it('mostra CODIGO_INVALIDO quando o código não confere', async () => {
    servidor.use(
      http.post('/encontros/enc_11111111/presencas', () =>
        HttpResponse.json({ erro: 'CODIGO_INVALIDO', mensagem: 'código inválido' }, { status: 422 }),
      ),
    )

    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-carla" />)

    await userEvent.type(screen.getByLabelText(/código/i), 'ZZZZZZ')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))

    expect(await screen.findByRole('alert')).toHaveTextContent('CODIGO_INVALIDO')
  })

  it('mostra NAO_INSCRITO quando o participante não está inscrito', async () => {
    servidor.use(
      http.post('/encontros/enc_11111111/presencas', () =>
        HttpResponse.json({ erro: 'NAO_INSCRITO', mensagem: 'não inscrito' }, { status: 403 }),
      ),
    )

    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-gabriela" />)

    await userEvent.type(screen.getByLabelText(/código/i), 'K7M2QX')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))

    expect(await screen.findByRole('alert')).toHaveTextContent('NAO_INSCRITO')
  })
})

import { useState } from 'react'
import { chamarApi, ErroApi } from '../../api/cliente.js'

export function TelaLeituraPresenca({ encontroId, usuarioId }) {
  const [codigo, setCodigo] = useState('')
  const [mensagem, setMensagem] = useState(null)
  const [erro, setErro] = useState(null)
  const [enviando, setEnviando] = useState(false)

  async function enviar(evento) {
    evento.preventDefault()
    setMensagem(null)
    setErro(null)
    setEnviando(true)

    try {
      await chamarApi(`/encontros/${encontroId}/presencas`, {
        metodo: 'POST',
        usuarioId,
        corpo: { codigo },
      })
      setMensagem('Presença registrada com sucesso.')
      setCodigo('')
    } catch (e) {
      setErro(e)
    } finally {
      setEnviando(false)
    }
  }

  return (
    <section>
      <h1>Registrar presença</h1>

      <form onSubmit={enviar}>
        <label>
          Código
          <input
            value={codigo}
            onChange={(e) => setCodigo(e.target.value)}
            maxLength={6}
            required
          />
        </label>
        <button type="submit" disabled={enviando}>
          Enviar
        </button>
      </form>

      {mensagem && <p role="status">{mensagem}</p>}
      {erro && (
        <p role="alert">
          {erro instanceof ErroApi ? erro.codigo : 'Não foi possível enviar a leitura.'}
        </p>
      )}
    </section>
  )
}

import 'fake-indexeddb/auto'
import { act, render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { http, HttpResponse } from 'msw'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { servidor } from '../../testes/servidor.js'
import { TelaLeituraPresenca } from './TelaLeituraPresenca.jsx'

function definirOnLine(valor) {
  Object.defineProperty(window.navigator, 'onLine', { configurable: true, value: valor })
}

beforeEach(async () => {
  await new Promise((resolve) => {
    const requisicao = indexedDB.deleteDatabase('semana-academica-presencas')
    requisicao.onsuccess = resolve
    requisicao.onerror = resolve
    requisicao.onblocked = resolve
  })
})

afterEach(() => {
  definirOnLine(true)
})

describe('Fila offline de presenças', () => {
  it('guarda a leitura no IndexedDB quando está offline e mostra quantas estão pendentes', async () => {
    definirOnLine(false)

    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-carla" />)

    await userEvent.type(screen.getByLabelText(/código/i), 'K7M2QX')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))

    expect(await screen.findByText(/1 leitura pendente/i)).toBeInTheDocument()
  })

  it('envia tudo que está na fila quando o evento online dispara', async () => {
    definirOnLine(false)

    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-carla" />)

    await userEvent.type(screen.getByLabelText(/código/i), 'K7M2QX')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))
    await screen.findByText(/1 leitura pendente/i)

    let corpoRecebido = null
    servidor.use(
      http.post('/encontros/enc_11111111/presencas', async ({ request }) => {
        corpoRecebido = await request.json()
        return HttpResponse.json(
          {
            id: 'pre_11111111',
            encontroId: 'enc_11111111',
            participanteId: 'p-carla',
            origem: 'qr_offline',
            lidoEm: corpoRecebido.lidoEm,
            registradaEm: '2026-10-19T21:00:00-03:00',
            justificativa: null,
          },
          { status: 201 },
        )
      }),
    )

    definirOnLine(true)
    await act(async () => {
      window.dispatchEvent(new Event('online'))
    })

    await waitFor(() => expect(screen.queryByText(/pendente/i)).not.toBeInTheDocument())
    expect(corpoRecebido.codigo).toBe('K7M2QX')
    expect(typeof corpoRecebido.lidoEm).toBe('string')
  })

  it('mantém a leitura na fila se o reenvio falhar de novo', async () => {
    definirOnLine(false)
    render(<TelaLeituraPresenca encontroId="enc_11111111" usuarioId="p-carla" />)
    await userEvent.type(screen.getByLabelText(/código/i), 'K7M2QX')
    await userEvent.click(screen.getByRole('button', { name: /enviar/i }))
    await screen.findByText(/1 leitura pendente/i)

    servidor.use(
      http.post('/encontros/enc_11111111/presencas', () =>
        HttpResponse.json({ erro: 'CODIGO_INVALIDO', mensagem: 'expirado' }, { status: 422 }),
      ),
    )

    definirOnLine(true)
    await act(async () => {
      window.dispatchEvent(new Event('online'))
    })

    expect(await screen.findByText(/1 leitura pendente/i)).toBeInTheDocument()
  })
})

const NOME_BANCO = 'semana-academica-presencas'
const NOME_LOJA = 'fila'

function abrirBanco() {
  return new Promise((resolve, reject) => {
    const requisicao = indexedDB.open(NOME_BANCO, 1)
    requisicao.onupgradeneeded = () => {
      requisicao.result.createObjectStore(NOME_LOJA, { keyPath: 'id', autoIncrement: true })
    }
    requisicao.onsuccess = () => resolve(requisicao.result)
    requisicao.onerror = () => reject(requisicao.error)
  })
}

export async function adicionarNaFila({ encontroId, codigo, lidoEm }) {
  const banco = await abrirBanco()
  return new Promise((resolve, reject) => {
    const transacao = banco.transaction(NOME_LOJA, 'readwrite')
    transacao.objectStore(NOME_LOJA).add({ encontroId, codigo, lidoEm })
    transacao.oncomplete = () => resolve()
    transacao.onerror = () => reject(transacao.error)
  })
}

export async function listarFila() {
  const banco = await abrirBanco()
  return new Promise((resolve, reject) => {
    const requisicao = banco.transaction(NOME_LOJA, 'readonly').objectStore(NOME_LOJA).getAll()
    requisicao.onsuccess = () => resolve(requisicao.result)
    requisicao.onerror = () => reject(requisicao.error)
  })
}

export async function removerDaFila(id) {
  const banco = await abrirBanco()
  return new Promise((resolve, reject) => {
    const transacao = banco.transaction(NOME_LOJA, 'readwrite')
    transacao.objectStore(NOME_LOJA).delete(id)
    transacao.oncomplete = () => resolve()
    transacao.onerror = () => reject(transacao.error)
  })
}

